const COOKIE="qbr_session",SESSION_DAYS=7;
function json(data,status=200,headers={}){return new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store",...headers}})}
function cookies(req){const out={};(req.headers.get("cookie")||"").split(";").forEach(x=>{const i=x.indexOf("=");if(i>0)out[x.slice(0,i).trim()]=decodeURIComponent(x.slice(i+1))});return out}
function b64(bytes){let s="";for(const b of new Uint8Array(bytes))s+=String.fromCharCode(b);return btoa(s).replaceAll("+","-").replaceAll("/","_").replaceAll("=","")}
async function passwordHash(password,salt){const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:new TextEncoder().encode(salt),iterations:100000,hash:"SHA-256"},key,256);return b64(bits)}
async function verifyPassword(password,salt,hash){const got=await passwordHash(password,salt);return got===hash||got+"="===hash}
async function auth(req,env){if(!env.DB)return null;const token=cookies(req)[COOKIE];if(!token)return null;return await env.DB.prepare("SELECT u.id,u.username,u.email,u.name,u.role,u.active,u.business_id,b.name business_name,b.slug business_slug,b.business_type,b.currency,b.vat_rate,b.timezone,b.invoice_prefix FROM sessions s JOIN users u ON u.id=s.user_id JOIN businesses b ON b.id=u.business_id WHERE s.token=? AND s.expires_at>? AND u.active=1 AND b.active=1").bind(token,Date.now()).first().catch(()=>null)}
async function requireAuth(req,env){const u=await auth(req,env);if(!u)return json({error:"Authentication required"},401);if(req.method!=="GET"&&req.method!=="HEAD"&&new URL(req.url).pathname!=="/api/subscription/request"){const b=await env.DB.prepare("SELECT trial_ends_at,subscription_status,subscription_ends_at FROM businesses WHERE id=?").bind(u.business_id).first();const now=Date.now(),status=String(b&&b.subscription_status||"");const expiry=status==="active"?Date.parse(b.subscription_ends_at||""):status==="trialing"?Date.parse(b.trial_ends_at||""):0;if((status!=="active"&&status!=="trialing")||!Number.isFinite(expiry)||expiry<=now)return json({error:"Your trial or subscription has expired. Submit a bank-transfer payment request from the Subscription section to restore access.",code:"subscription_required"},402)}return u}
async function sessionCookie(user,env){const token=crypto.randomUUID()+"-"+crypto.randomUUID(),exp=Date.now()+SESSION_DAYS*86400000;await env.DB.prepare("INSERT INTO sessions(token,user_id,expires_at) VALUES(?,?,?)").bind(token,user.id,exp).run();return COOKIE+"="+token+"; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age="+(SESSION_DAYS*86400)}
function clearCookie(){return COOKIE+"=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0"}
function clean(o){return o&&typeof o==="object"?Object.fromEntries(Object.entries(o).filter(([k,v])=>v!==undefined)):{}}
const ROLE_LABELS={admin:"Owner",manager:"Manager",staff:"Rental Staff",accountant:"Accountant",maintenance:"Maintenance"};
const ROLE_PERMISSIONS={admin:["*"],manager:["dashboard.read","bookings.read","bookings.write","fleet.read","fleet.write","customers.read","customers.write","services.read","reports.read","finance.read","pickup.write"],staff:["dashboard.read","bookings.read","bookings.write","fleet.read","customers.read","customers.write","services.read","pickup.write"],accountant:["dashboard.read","bookings.read","customers.read","services.read","reports.read","finance.read","finance.write","expenses.read","expenses.write"],maintenance:["fleet.read","fleet.write","maintenance.read","maintenance.write"]};
function can(u,p){return !!u&&(u.role==="admin"||(ROLE_PERMISSIONS[u.role]||[]).indexOf(p)>=0||(ROLE_PERMISSIONS[u.role]||[]).indexOf("*")>=0)}
function deny(p){return json({error:"Permission required: "+p},403)}
async function audit(env,u,action,entityType,entityId,details){try{await env.DB.prepare("INSERT INTO audit_log(business_id,user_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?,?)").bind(u.business_id,u.id,action,entityType,entityId||null,JSON.stringify(details||{})).run()}catch(e){}}
function roleLabel(r){return ROLE_LABELS[r]||r}
