function fleetWorkspace(){var rows=state.data.fleet||[];var counts={available:0,reserved:0,rented:0,maintenance:0};rows.forEach(function(x){counts[x.status]=(counts[x.status]||0)+1});return header("Fleet Management","Live asset health, utilization and maintenance readiness.",'<button class="btn primary" data-action="vehicle">+ Add vehicle</button>')+'<div class="cards"><div class="card"><div class="label">Fleet size</div><div class="value">'+rows.length+'</div></div><div class="card"><div class="label">Available</div><div class="value green">'+(counts.available||0)+'</div></div><div class="card"><div class="label">On rental</div><div class="value">'+(counts.rented||0)+'</div></div><div class="card"><div class="label">Maintenance</div><div class="value">'+(counts.maintenance||0)+'</div></div></div><div class="section"><div class="tableWrap"><table><thead><tr><th>Vehicle</th><th>Status</th><th>Odometer</th><th>Fuel</th><th>Next service</th><th>Open damage</th><th>Inspection</th><th></th></tr></thead><tbody>'+rows.map(function(x){return '<tr><td><strong>'+esc(x.name)+'</strong><small>'+esc(x.registration||x.category||"")+'</small></td><td><span class="pill">'+esc(x.status)+'</span></td><td>'+Number(x.current_odometer||0)+'</td><td>'+esc(x.current_fuel_level==null?"—":x.current_fuel_level+"%")+'</td><td>'+esc(x.next_service_date||"Not scheduled")+'</td><td>'+esc(x.open_damage_count||0)+'</td><td>'+esc(x.last_inspection||"Never")+'</td><td><button class="btn" data-fleet-inspect="'+esc(x.id)+'">Inspect</button> <button class="btn" data-fleet-damage="'+esc(x.id)+'">Damage</button></td></tr>'}).join("")+(rows.length?"":'<tr><td colspan="8" class="empty">No vehicles yet.</td></tr>')+'</tbody></table></div></div>'}
