function invoice(id){var r=state.data.rentals.find(function(x){return String(x.id)===String(id)});if(!r)return;var customer=state.data.customers.find(function(x){return String(x.id)===String(r.customer_id)})||{},vehicle=state.data.vehicles.find(function(x){return String(x.id)===String(r.vehicle_id)})||{},service=state.data.services.find(function(x){return String(x.id)===String(r.service_id)})||{};var business=state.user||{};var w=window.open("","_blank");if(!w)return alert("Please allow pop-ups to print the invoice.");w.document.write('<!doctype html><html><head><title>Invoice '+esc(r.invoice_no||r.id)+'</title><style>body{font-family:Arial,sans-serif;color:#17253a;margin:0;padding:35px;background:#f5f6f3}.sheet{max-width:800px;margin:auto;background:#fff;padding:40px;box-shadow:0 4px 25px #0001}.head{display:flex;justify-content:space-between;border-bottom:2px solid #17253a;padding-bottom:22px}.brand{font-size:25px;font-weight:800}.muted{color:#687268}.right{text-align:right}.title{font-size:28px;font-weight:800;margin:28px 0 18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.box{background:#f5f7f3;padding:15px;border-radius:8px}.items{width:100%;border-collapse:collapse;margin-top:25px}.items th,.items td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.items th:last-child,.items td:last-child{text-align:right}.totals{margin-left:auto;width:300px;margin-top:20px}.totals div{display:flex;justify-content:space-between;padding:7px}.grand{font-size:18px;font-weight:800;border-top:2px solid #17253a;margin-top:5px;padding-top:12px!important}.foot{margin-top:35px;padding-top:15px;border-top:1px solid #ddd;font-size:12px}.print{position:fixed;right:20px;top:20px;padding:12px 18px;background:#17253a;color:white;border:0;border-radius:8px}@media print{body{background:#fff;padding:0}.sheet{box-shadow:none;padding:0}.print{display:none}}</style></head><body><button class="print" onclick="window.print()">Download / Save PDF</button><div class="sheet"><div class="head"><div><div class="brand">'+esc(business.business_name||"Rental Business")+'</div><div class="muted">Quad & Buggy Rental</div></div><div class="right"><strong>INVOICE</strong><br>'+esc(r.invoice_no||"")+'<br><span class="muted">'+esc(r.created_at||"")+'</span></div></div><div class="title">Rental Invoice</div><div class="grid"><div class="box"><strong>Billed to</strong><br>'+esc(customer.name||"Customer")+'<br>'+esc(customer.phone||"")+'<br>'+esc(customer.email||"")+'<br>'+esc(customer.nationality||"")+'</div><div class="box"><strong>Rental details</strong><br>Vehicle: '+esc(vehicle.name||"")+'<br>Registration: '+esc(vehicle.registration||"")+'<br>Start: '+esc(r.start_at||"")+'<br>End: '+esc(r.end_at||"")+'</div></div><table class="items"><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody><tr><td>'+esc(vehicle.name||"Rental")+'</td><td>'+esc(r.quantity||1)+'</td><td>'+money(r.unit_price||0)+'</td><td>'+money(r.subtotal||0)+'</td></tr>'+(r.service_id&&service.name?'<tr><td>'+esc(service.name)+'</td><td>1</td><td>'+money(service.price||0)+'</td><td>'+money(service.price||0)+'</td></tr>':"")+'</tbody></table><div class="totals"><div><span>Subtotal</span><span>'+money(r.subtotal||0)+'</span></div><div><span>Discount</span><span>- '+money(r.discount||0)+'</span></div><div><span>VAT ('+esc(r.vat_rate||0)+'%)</span><span>'+money(r.vat_amount||0)+'</span></div><div class="grand"><span>Total</span><span>'+money(r.total||0)+'</span></div><div><span>Deposit</span><span>'+money(r.deposit||0)+'</span></div><div><span>Payment status</span><span>'+esc(r.payment_status||"unpaid")+'</span></div></div><div class="foot">Thank you for choosing '+esc(business.business_name||"our business")+'. This invoice was generated by RentalOS.</div></div></body></html>');w.document.close()}
