function migrationWorkspace(){return header("Data Migration","Import your existing rental software data into RentalOS.")+'<div class="card migrationHero"><h2>Bring your history with you</h2><p>Export CSV from your current software and upload it here. RentalOS auto-matches common column names, skips duplicates and records an import audit batch.</p><div class="migrationGrid"><div class="migrationStep"><b>01 · EXPORT</b><span>Customers, vehicles and historical rentals as CSV.</span></div><div class="migrationStep"><b>02 · UPLOAD</b><span>Maximum 2.5 MB / 10,000 rows.</span></div><div class="migrationStep"><b>03 · VERIFY</b><span>See imported vs skipped rows before continuing your operation.</span></div></div></div><div class="card"><div class="form"><div class="field"><label>Data type</label><select id="import-entity"><option value="customers">Customers</option><option value="vehicles">Vehicles</option><option value="rentals">Historical rentals</option></select></div><div class="field"><label>CSV file</label><input id="import-file" type="file" accept=".csv,text/csv"></div></div><div style="display:flex;gap:10px;margin-top:12px;flex-wrap:wrap"><button class="btn" data-import-template>Download template</button><button class="btn primary" data-import-run>Upload & import</button></div><div id="import-result" class="hint" style="margin-top:12px">No import started.</div></div><div class="card"><h3>Accepted columns</h3><div class="hint"><b>Customers:</b> name, phone, email, nationality, id_reference<br><b>Vehicles:</b> name, category, registration, status, rate_per_hour, current_odometer, insurance_expiry, registration_expiry<br><b>Historical rentals:</b> invoice_no, customer_name, vehicle_registration, start_at, end_at, total, vat_rate, vat_amount, deposit, payment_status, status</div></div>'}
